-- DIRA LEARN - production initialization, STEP 1b (generated by build_bundle.py - do not edit by hand)
-- For a database where migrations 01-37 are applied and recorded but the seed did not complete (state found in
-- production on 21 Nov 2026: 403 on /rest/v1/profiles, no organisation/programme/curriculum data).
-- Contents, byte for byte from the repository: migrations 38-39 (38: explicit Data API grants; 39: interim
-- safeguarding access for Super Administrators) and seed.sql.
-- Run ONLY with psql, ONLY after 00b_precheck_partial_readonly.sql said CONTINUE and a backup was taken:
--   psql "<session-pooler connection string>" -v ON_ERROR_STOP=1 -X -f supabase/production_init/01b_continue_after_37.sql
-- It changes no sign-in account, password, profile role or existing record. The seed only adds missing reference and
-- curriculum rows (it is safe to re-run; a second run changes nothing).
--   7189bb54367df07a7774fa15ca5d2771e4db319640846b401cd635eb87753c1a  supabase/migrations/20260101000038_explicit_api_grants.sql
--   3a0ef2ef3baa5bdd910cbb5887f9639d4db686debe89ef0a1d1708bdc96a7f17  supabase/migrations/20260101000039_safeguarding_interim_super_admin.sql
--   4c658bceb529f2fa9117fd59d97fd52f7e3c53bf5866137e90107d682ad3ee54  supabase/seed.sql
\set ON_ERROR_STOP on
\set QUIET on
\echo '== guard: migrations 01-37 recorded, 38 onward not yet'
do $guard$
declare v text;
begin
  if to_regclass('supabase_migrations.schema_migrations') is null then
    raise exception 'STOP: no migration history. Use 01_initialize_production.sql for an empty database. Nothing was changed.';
  end if;
  execute 'select string_agg(version, '','' order by version) from supabase_migrations.schema_migrations' into v;
  if v is distinct from (select string_agg(to_char(20260101000000 + g, 'FM00000000000000'), ',' order by g) from generate_series(1, 37) g) then
    raise exception 'STOP: migration history is not exactly 01-37 (found %). Run 00b_precheck_partial_readonly.sql and send it to Claude. Nothing was changed.', coalesce(v, 'none');
  end if;
  if to_regclass('public.profiles') is null then
    raise exception 'STOP: public.profiles does not exist although 01-37 are recorded. Nothing was changed.';
  end if;
  raise notice 'guard passed: % sign-in account(s) and % profile(s) will be kept', (select count(*) from auth.users), (select count(*) from public.profiles);
end $guard$;

\echo '== migration 20260101000038 explicit_api_grants'
begin;
-- Migration 38 - explicit Data API grants (21 Nov 2026).
-- WHY: in production every signed-in request to public.profiles returned 403 ("permission denied for table profiles"),
-- although the profile existed with role super_admin and status active. Cause: migrations 01-37 never granted table
-- privileges to the API roles; they relied on Supabase granting every new public table, sequence and function to anon,
-- authenticated and service_role automatically. Supabase stopped doing that (new projects since 30 May 2026, all
-- projects since 30 Oct 2026). Reproduced locally on 21 Nov 2026: 5 of 106 tables readable by signed-in users.
-- WHAT: writes the authored intent of migrations 01-37 down as explicit grants (generated by
-- tools/release/generate_grants_38.py, reviewed):
--   * signed-in users (authenticated): only SELECT/INSERT/UPDATE/DELETE that a permissive RLS policy allows and that the
--     earlier migrations did not deliberately withhold. RLS stays on everywhere and still decides WHICH ROWS. Never
--     TRUNCATE, REFERENCES or TRIGGER (the old automatic defaults granted those too; they are removed here).
--   * signed-out visitors (anon): no table at all; only check_request() (API pre-request check) and verify_certificate().
--   * service_role (Edge Functions, server only): all tables, sequences and functions in public.
--   * functions: execute exactly as authored (122 for signed-in users; the 26 internal ones stay server-only).
-- SAFE on both kinds of project: on a project that still had the old automatic grants it narrows them to the intent; on
-- a new-style project it adds the missing grants. No data, row, policy or function body is changed.
-- SELF-CHECK at the end: the migration aborts (and changes nothing) if the result breaks any rule above.
-- Rollback: supabase/rollback/20260101000038_explicit_api_grants_down.sql restores the privileges recorded below exactly.

-- ============ 1. record the privileges as they are now (for an exact rollback) ============
create table if not exists grants_38_backup (
  object_kind text not null, object_name text not null, grantee text not null, privilege text not null,
  recorded_at timestamptz not null default now(),
  primary key (object_kind, object_name, grantee, privilege));
alter table grants_38_backup enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'grants_38_backup' and policyname = 'dira_active_account') then
    create policy dira_active_account on grants_38_backup as restrictive for all to authenticated
      using ((select account_is_active())) with check ((select account_is_active()));
  end if;
end $$;
revoke all on grants_38_backup from anon, authenticated;
grant select, insert, update, delete on grants_38_backup to service_role;

insert into grants_38_backup(object_kind, object_name, grantee, privilege)
select 'relation', c.oid::regclass::text, coalesce(r.rolname, 'PUBLIC'), a.privilege_type
  from pg_class c cross join lateral aclexplode(c.relacl) a left join pg_roles r on r.oid = a.grantee
 where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p', 'v', 'm', 'S') and c.relname <> 'grants_38_backup'
   and coalesce(r.rolname, 'PUBLIC') in ('anon', 'authenticated', 'service_role', 'PUBLIC')
union all
select 'function', p.oid::regprocedure::text, coalesce(r.rolname, 'PUBLIC'), a.privilege_type
  from pg_proc p cross join lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a left join pg_roles r on r.oid = a.grantee
 where p.pronamespace = 'public'::regnamespace and coalesce(r.rolname, 'PUBLIC') in ('anon', 'authenticated', 'service_role', 'PUBLIC')
on conflict do nothing;

-- ============ 2. start from nothing for the API roles (no broad grants survive) ============
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke execute on all functions in schema public from public, anon, authenticated;

-- ============ 3. server side ============
grant select, insert, update, delete on all tables in schema public to service_role;
grant usage, select, update on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;

-- ============ 4. explicit grants (generated, reviewed) ============
