insert into organizations(id,name) values ('00000000-0000-0000-0000-000000000001','DIRA Foundation') on conflict do nothing;
insert into roles(code,label) values ('super_admin','Super Administrator'),('programme_director','Programme Director'),('programme_coordinator','Programme Coordinator'),('trainer','Trainer / Facilitator'),('me_officer','M&E Officer'),('mentor','Mentor'),('participant','Participant'),('applicant','Applicant') on conflict do nothing;
insert into programmes(id,organization_id,name,version,is_approved) values ('00000000-0000-0000-0000-0000000000a1','00000000-0000-0000-0000-000000000001','DIRA LEARN',1,false) on conflict do nothing;
insert into tracks(programme_id,code,name,focus,position) values ('00000000-0000-0000-0000-0000000000a1','digital','Digital Marketing','Reach and win customers online. Learners build a business''s online presence, understand their audience, plan and design content, write persuasive copy, use WhatsApp Business, search and simple advertising, measure results, and finish by building and presenting a basic digital marketing campaign for a real Kenyan business, cause or their own idea.',1) on conflict do nothing;
insert into tracks(programme_id,code,name,focus,position) values ('00000000-0000-0000-0000-0000000000a1','ai','AI Tools','Work smarter with AI, responsibly. Learners understand how AI tools work, write strong prompts, use AI for research, writing, images, presentations, productivity and business tasks, learn simple automation, check AI outputs for accuracy, privacy and bias, and finish by building and demonstrating an AI-assisted solution for a real need.',2) on conflict do nothing;
insert into tracks(programme_id,code,name,focus,position) values ('00000000-0000-0000-0000-0000000000a1','content','Content Creation','Tell stories people stop for. Learners plan content with a strategy, tell stories, shoot photos and video on a phone with good light, composition and sound, edit video and audio, write captions, design graphics with a consistent brand, use content responsibly and legally, and finish with a content portfolio and a creative project for a real brief.',3) on conflict do nothing;
insert into tracks(programme_id,code,name,focus,position) values ('00000000-0000-0000-0000-0000000000a1','entrepreneurship','Entrepreneurship & Business','Turn an idea into a tested business concept. Learners spot opportunities, understand customer problems and markets, design a value proposition and business model, learn practical money skills (costing, pricing, revenue, expenses and cash flow), market and sell ethically with good customer service, test their idea with real customers, and pitch a business concept.',4) on conflict do nothing;
-- Curriculum session records (V13, generated by tools/curriculum/build_v13.py). Durations are the approved timetable: 110, 115, then 120 minutes.
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) values ('00000000-0000-0000-0000-0000000000a1',null,1,1,'Self-leadership, confidence and wellbeing','Know your strengths and values, start your personal brand, set a four-week goal and build habits that keep you well and confident at work.',110,array['Describe at least three personal strengths, two interests and two values, with an example of each from real life','Write a first-draft personal brand statement (two sentences) based on strengths, values and the help they can offer others','Set one SMART four-week learning goal and name the first step they will take this week','Practise three confident workplace behaviours (introducing yourself, asking for help, accepting feedback)','Identify two wellbeing habits and one support route they can use during the programme','Explain the programme expectations, the learning agreement and how to raise a safeguarding concern']::text[],array['Welcome and learning agreement','Icebreaker - two truths and a strength','Values, confidence and self-leadership mini-workshop','Strengths map and personal brand statement','Confidence at work - practice rounds','Wellbeing and resilience','SMART goal and accountability partner','Reflection and exit ticket']::text[],'{}'::text[],'Completed strengths map (strengths, interests, values, help I can offer); First-draft personal brand statement (two sentences); Goal card with a SMART four-week goal, first step and two wellbeing habits; Accountability partner agreed; Baseline self-assessment and exit ticket submitted','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13') on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) values ('00000000-0000-0000-0000-0000000000a1',null,1,2,'Digital foundations, AI awareness and communication','Work safely and professionally online, understand what AI can and cannot do, communicate clearly, build a professional online presence and pitch yourself in 30 seconds.',115,array['Apply five rules of professional online conduct (email, WhatsApp, video calls) and organise a programme folder','Explain three things AI tools can help with, three limitations and why human checking is always required','Write a clear prompt and improve the output using verification and their own judgement','Write a professional message and an email with a clear subject, greeting, request and sign-off','Improve one professional online profile (LinkedIn, Instagram bio, WhatsApp about or Facebook) so it matches their personal brand','Deliver a 30-second self-pitch and give respectful feedback to a peer','Recognise common online scams and privacy risks and know how to respond','Confirm their specialist track choice with a reason']::text[],array['Recap and digital confidence pulse check','Digital foundations and professional conduct','AI awareness and prompt practice','Clear communication practice','Professional online presence and self-pitch','Online safety scenarios','Core module check and track confirmation','Reflection, digital safety checklist and next steps']::text[],'{}'::text[],'Programme folder with the standard file names; Short professional introduction message created with AI support, improved and checked by the learner, with a one-line AI disclosure; Professional application email; Improved online profile (or paper draft) matching the personal brand statement; Delivered 30-second self-pitch; Completed digital safety checklist and core knowledge check; Confirmed specialist track','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 8 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13') on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,2,3,'Digital marketing foundations, online presence and reputation','How digital marketing works, the main channels and strategies, digital footprint and online reputation, and building a strong personal and business presence. Learners choose their campaign brief.',120,array['Explain digital marketing and the customer journey (awareness, consideration, conversion, loyalty) using a local business example','Compare owned, earned and paid channels and name at least five digital channels used by Kenyan businesses','Audit a digital footprint (personal and business) and identify three risks and three improvements','Respond professionally to a negative online review','Improve one personal or business profile for clarity, trust and contact','Choose a campaign brief and draw a first channel map for it']::text[],array['Welcome to Digital Marketing and track overview','What digital marketing is, the customer journey and channels','Digital footprint and online reputation','Demonstration - footprint audit and review reply','Stretch break','Presence audit and profile improvement','Choose your campaign brief and draw a channel map','Knowledge check','Wrap-up and homework']::text[],'{}'::text[],'Personal digital footprint audit (kept private) with privacy settings fixed; Improved personal or business profile (bio, image, contact, trust signals); One-paragraph campaign brief; Channel map with two main channels and one support channel','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='digital' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,2,4,'Target audiences, social media marketing and WhatsApp Business','Define target audiences and customer personas, use Facebook, Instagram, TikTok and LinkedIn for marketing, and set up WhatsApp Business to serve and sell to customers.',120,array['Explain target audience, segmentation and customer persona with examples','Build a customer persona from real customer answers (demographics, needs, problems, habits, where they spend time online)','Compare Facebook, Instagram, TikTok and LinkedIn by audience, content formats and best uses for marketing','Explain in simple terms how feeds decide what people see (relevance, engagement, consistency)','Set up or plan a WhatsApp Business profile with a catalogue, greeting, away message, quick replies and labels','Use broadcast lists and status responsibly, with customer consent','Choose the platforms and posting frequency for their campaign']::text[],array['Recap and customer answers','Target audiences and customer personas','Build your customer persona','Social media marketing on four platforms','Stretch break','Demonstration and practice - WhatsApp Business','Platform plan for your campaign','Knowledge check','Wrap-up and homework']::text[],'{}'::text[],'Customer persona based on real customer information; WhatsApp Business plan (or a set-up profile on a business number); Platform plan with formats, posting times and reasons','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='digital' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,3,5,'Branding, content planning and marketing graphics','Build a simple brand identity, plan content with pillars and a two-week calendar, and design marketing graphics that communicate clearly.',120,array['Explain branding and brand identity (name, promise, personality, voice, colours, fonts, logo) with local examples','Create a brand mini-kit for their campaign business','Define three or four content pillars and a content mix for their persona','Build a two-week content calendar with dates, platforms, formats, captions ideas and goals','Apply visual communication principles (hierarchy, contrast, alignment, white space, readable text) to a marketing graphic','Design two marketing graphics in Canva (or a similar free tool) that follow the brand mini-kit']::text[],array['Recap and what businesses post','Branding and brand identity','Create your brand mini-kit','Content pillars and the content calendar','Stretch break','Build your two-week content calendar','Visual communication principles','Demonstration and practice - designing marketing graphics','Peer review and knowledge check','Wrap-up and homework']::text[],array['Digital footprint and online safety','Introduction to digital marketing','Social media marketing (Facebook, Instagram, TikTok, LinkedIn)','Content planning and creation']::text[],'Brand mini-kit (promise, personality, voice, colours, fonts, photo style); Content pillars and a two-week content calendar; Two branded marketing graphics (feed post and status or story)','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='digital' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,3,6,'Copywriting, customer engagement and search engine optimisation','Write persuasive, honest marketing copy, turn engagement into customers on WhatsApp and social media, and use search engine optimisation basics including Google Business Profile.',120,array['Write captions using the AIDA and Problem-Agitate-Solution structures, with a clear call to action','Turn product features into customer benefits','Write honest marketing copy that avoids false or misleading claims','Use engagement and conversion techniques (fast replies, social proof, clear offers, easy ordering and payment)','Handle an enquiry from first message to confirmed order in a role-play','Explain how search engines rank results and the basics of keywords and local SEO','Draft a Google Business Profile and a keyword list for their business']::text[],array['Recap and caption hunt','Copywriting and persuasive messaging','Write your campaign captions','Customer engagement and conversion','Stretch break','Role-play - from enquiry to order','Search engine optimisation fundamentals and Google Business Profile','Keyword list and Google Business Profile draft','Knowledge check','Wrap-up and homework']::text[],array['Canva for marketing graphics','Marketing copywriting, captions and calls to action','WhatsApp Business']::text[],'Three finished captions with hooks and calls to action; Enquiry-to-order conversation script (from the role-play); Keyword list (ten phrases, five priority); Google Business Profile draft','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks