insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,4,7,'Online advertising, campaign budgeting, analytics and campaign build','Understand online advertising, plan a small KES budget, choose measures of success, and build the full campaign for the final project.',120,array['Explain the difference between boosting a post and creating an ad in Meta Ads Manager, and give an overview of Google Ads','Choose an ad objective, audience, creative and budget for a small campaign','Build a campaign budget in KES covering content, data, ads and other costs, with a cost-per-result estimate','Explain reach, impressions, engagement rate, clicks, messages, conversions, cost per result and return on ad spend','Read basic insights on Facebook, Instagram or WhatsApp Business and track offline results with simple codes','Assemble a complete campaign plan with a SMART objective, KPIs and a timeline','Improve the campaign based on peer testing']::text[],array['Recap and results from your first post','Introduction to online advertising','Campaign planning and budgeting in KES','Marketing analytics and measuring results','Stretch break','Campaign build','Peer testing and revision','Showcase preparation and homework']::text[],array['Digital advertising fundamentals','SEO fundamentals','Marketing analytics and measuring campaign performance','Developing a practical digital marketing strategy']::text[],'Complete campaign plan (all twelve sections); Campaign budget in KES with cost-per-result estimate (or zero-budget time plan); KPI list with targets and a tracking sheet; Peer-test feedback and a revision list','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='digital' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,4,8,'Digital marketing campaign showcase','Present your digital marketing campaign, answer questions, give and receive feedback, pitch yourself professionally and plan your next 30 days.',120,array['Present a basic digital marketing campaign clearly in three minutes, explaining objective, audience, channels, content, budget and measures','Report real results or test findings honestly and say what they would improve','Answer questions about their choices with evidence','Give and receive feedback professionally using the showcase rubric','Pitch themselves and their campaign as a portfolio piece to an employer or client','Write a 30-day action plan for continuing to market the business or to find marketing work']::text[],array['Showcase set-up and expectations','Campaign presentations and questions - block 1','Stretch break','Campaign presentations and questions - block 2','Feedback round','Pitching yourself and workplace readiness','30-day action plan','Celebration and close']::text[],'{}'::text[],'Presented digital marketing campaign (final project) with rubric score and feedback; One-page campaign case study for the portfolio; 30-day action plan; Written feedback given to two peers','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 3 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='digital' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,2,3,'Understanding AI, AI tools and responsible use','What artificial intelligence is, the main types of AI tools and what they are used for, and the principles of responsible and ethical AI use.',120,array['Explain in plain words what AI, machine learning and generative AI are, and how a chat assistant produces an answer','Identify AI already used in everyday Kenyan life (spam filters, maps, fraud alerts, translation, customer-care chatbots)','Name at least six types of AI tools and a practical use for each','Complete three AI-assisted tasks and record what the learner checked or changed','Explain five principles of responsible AI use (honesty, privacy, accuracy, fairness, human responsibility)','Agree and sign a group AI use code']::text[],array['Welcome to AI Tools and track overview','What AI is and how it works','Types and uses of AI tools','Demonstration - three AI tasks and what needed checking','Stretch break','Your three AI tasks','Responsible AI scenarios and group AI use code','Knowledge check','Wrap-up and homework']::text[],'{}'::text[],'AI task log with three completed tasks and checks; Signed group AI use code with the disclosure line format','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='ai' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,2,4,'Prompt engineering, AI for research and learning, and fact-checking','Write clear and effective prompts, use AI to research and learn, and evaluate and fact-check AI outputs before using them.',120,array['Use the RTCF prompt framework (Role, Task, Context, Format) plus constraints and examples','Apply at least four prompt patterns (step by step, ask me questions first, critique and improve, give examples)','Iterate a prompt and explain why the output improved','Use AI to learn a topic (explain, quiz, summarise, compare) and to plan research','Fact-check AI outputs using lateral reading and official or reliable sources','Produce a short research brief in which every key claim has a verified source']::text[],array['Recap and task log review','Prompt engineering - framework and patterns','Prompt lab','AI for research and learning','Stretch break','Demonstration and practice - fact-checking AI outputs','Verified research brief','Knowledge check','Wrap-up and homework']::text[],'{}'::text[],'Prompt library v1 (three tested prompts); Fact-check record for one AI answer; Verified research brief with sources and disclosure','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='ai' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,3,5,'AI-assisted writing, images, creative work and presentations','Use AI responsibly to draft and improve writing, create images and creative work, and build presentations, keeping your own voice and checking every output.',120,array['Use the human-first-and-last workflow (plan, prompt, edit, check, disclose) for writing','Use AI to draft, edit, shorten, change tone and translate, while keeping their own voice and facts','Write image prompts with subject, setting, style, lighting and composition, and evaluate results','Explain the risks of AI images (deepfakes, consent, bias, copyright uncertainty) and label AI images honestly','Plan and build a five-slide presentation with AI support and check it for accuracy and clarity','Disclose AI assistance appropriately']::text[],array['Recap and project brief check','AI-assisted writing','Write with AI in your own voice','AI images and creative work','Stretch break','Create an AI-assisted image','AI for presentations - demonstration and build','Gallery review and knowledge check','Wrap-up and homework']::text[],'{}'::text[],'AI-assisted writing piece (draft and edited version); Labelled AI-assisted image with prompt notes; Five-slide presentation with speaker notes and disclosure','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='ai' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,3,6,'AI for productivity, business and automation, with privacy, bias and limits','Use AI for everyday tasks and small business activities, understand simple automation, and manage privacy, bias and the limitations of AI.',120,array['Use AI for at least four productivity tasks (planning, summarising, organising, drafting, spreadsheet help)','Use AI for small business activities (customer replies, product descriptions, simple market research, social posts) with checks','Explain automation (trigger, action, human check) and identify three automation opportunities in a workflow','Explain how personal data must be protected when using AI, with reference to Kenya''s Data Protection Act 2019','Identify bias and limitations in AI outputs, including language and local-context gaps','Map a routine workflow and build a reusable prompt set with human checkpoints']::text[],array['Recap and time audit','AI for productivity and everyday tasks','AI-assisted business activities','Introduction to automation','Stretch break','Privacy, bias and limitations','Workflow map and reusable prompt set','Knowledge check','Wrap-up and homework']::text[],'{}'::text[],'Workflow map with H, AI and A steps, data points and human checks; Reusable prompt set (tested); Updated prompt library','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='ai' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,4,7,'AI project build and testing','Build an AI-assisted solution for a real brief, evaluate it with the AI quality checklist, test it with a real user and prepare a demonstration.',120,array['Define the problem, user, AI role and success test for the project','Build a working AI-assisted solution using a documented prompt set and tools','Evaluate the solution with the AI quality checklist and fix problems','Test the solution with a real user and record their feedback','Prepare a three-minute demonstration with an AI-use disclosure']::text[],array['Project check-in','Designing your solution','Build','Stretch break','Evaluate and user-test','Revise and prepare the demonstration','Showcase briefing and homework']::text[],'{}'::text[],'Completed project design canvas; Working AI-assisted solution with documented prompt set and user instructions; AI quality checklist and user test record; Draft three-minute demonstration','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 3 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='ai' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,4,8,'AI tools showcase','Demonstrate your AI-assisted solution, explain your responsible choices, give and receive feedback, pitch yourself and plan your next 30 days.',120,array['Demonstrate an AI-assisted solution clearly in three minutes','Explain the human checks, privacy protections and disclosure in the solution','Report user feedback and evaluation results honestly','Give and receive feedback professionally using the rubric','Pitch themselves and the project as portfolio evidence','Write a 30-day plan for using AI skills responsibly']::text[],array['Showcase set-up and expectations','Demonstrations and questions - block 1','Stretch break','Demonstrations and questions - block 2','Feedback round and responsible AI reflection','Pitching yourself and workplace readiness','30-day action plan','Celebration and close']::text[],'{}'::text[],'Demonstrated AI-assisted solution (final project) with rubric score and feedback; One-page AI project case study with disclosure; 30-day action plan; Written feedback given to two peers','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 3 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='ai' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,2,3,'Content strategy, storytelling and platform formats','Plan content with a clear purpose, audience and niche, tell stories with a hook, a middle and an ending, and choose the right formats for each platform.',120,array['Write a content strategy one-pager (purpose, audience, niche, goals, pillars, platforms, posting rhythm)','Explain the difference between creator content and brand content','Apply a story structure (hook, build, payoff, call to action) and the ''show, don''t tell'' principle','Compare content formats and specifications for TikTok, Instagram, YouTube, Facebook, WhatsApp status, LinkedIn and podcasts','Choose a real brief for the creative project','Storyboard a 30 to 60-second piece']::text[],array['Welcome to Content Creation and track overview','Content strategy and planning','Storytelling','Content formats for different platforms','Stretch break','Demonstration - from idea to storyboard','Strategy one-pager, brief and storyboard','Peer pitch and knowledge check','Wrap-up and homework']::text[],'{}'::text[],'Content strategy one-pager; Creative project brief; Storyboard for a 30 to 60-second piece','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='content' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,2,4,'Smartphone photography, lighting, composition and mobile video','Take clear, well-lit, well-composed photos and short videos on a phone, and capture clean sound.',120,array['Apply composition techniques (rule of thirds, leading lines, framing, angles, clean backgrounds, symmetry)','Use phone camera features (gridlines, focus and exposure lock, portrait mode, HDR) and avoid digital zoom','Use natural light well (window light, golden hour, avoiding harsh midday sun, simple reflectors)','Film stable shots in the right orientation using wide, medium and close-up shots and B-roll','Capture clean audio (quiet location, mic close to the speaker, avoiding wind and echo)','Shoot a five-photo set and the clips for their storyboard, with consent']::text[],array['Recap and hooks you found','Composition and phone camera basics','Lighting','Mobile video production','Stretch break','Capturing clean sound','Practical shoot','Peer review of shots','Wrap-up and homework']::text[],'{}'::text[],'Five-photo set for the brief; Storyboard clips including B-roll and a clean audio clip (complete or in progress); Peer-reviewed shot checklist with a reshoot plan','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='content' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,3,5,'Video editing, audio and sound, captions and creative writing','Edit a short video on a phone, improve audio and add music legally, write on-screen captions and post captions, and export for each platform.',120,array['Apply editing principles (hook first, cut on action, pacing, jump cuts, sequences, minimal transitions)','Edit a 30 to 60-second video in a free mobile editor (trim, split, arrange, speed, text, audio, colour)','Improve audio (levels, noise reduction, voice-over) and use music legally (platform libraries, royalty-free, licensed)','Add accurate on-screen captions for accessibility and check auto-captions','Write a post caption using creative writing techniques with a hook and call to action','Export with the right settings for each platform']::text[],array['Recap and footage check','Editing principles and demonstration','Edit your video','Stretch break','Audio and sound - editing and legal music','Captions and creative writing','Finish and export','Screening and knowledge check','Wrap-up and homework']::text[],'{}'::text[],'Edited 30 to 60-second video with captions and legal audio; Post caption with hook and call to action','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='content' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,3,6,'Graphic design, visual storytelling, branding and responsible content','Apply graphic design fundamentals, tell stories visually in carousels and posters, keep content consistent with a brand, and use content legally and responsibly.',120,array['Apply the design principles contrast, repetition, alignment and proximity, plus typography and colour basics','Use grids and hierarchy to lay out a poster and a social post','Tell a story across a carousel (hook slide, steps or before-and-after, payoff, call to action)','Create a content brand kit (colours, fonts, logo or signature, templates, voice, recurring series)','Explain copyright basics in Kenya, licences, Creative Commons, consent and model releases, and platform rules','Keep a credit and consent log for all content']::text[],array['Recap and video results','Graphic design fundamentals','Visual storytelling','Content branding and consistency','Stretch break','Copyright and responsible content use','Design a branded post, poster and carousel','Peer critique and knowledge check','Wrap-up and homework']::text[],array['Visual hierarchy','Consistent branding','Consent and credit for people, images and music']::text[],'Content brand kit with three templates; Branded post, poster and carousel; Credit and consent log (started)','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='content' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,4,7,'Portfolio development and creative project build','Build a content portfolio and complete the creative project for your brief, test it with peers and prepare the showcase.',120,array['Explain what makes a strong content portfolio (best three to five pieces, variety, results, story behind each piece)','Choose a portfolio platform (Google Drive folder, Behance, Instagram highlights, a simple website), and submit it through a restricted-access link or DIRA LEARN','Write a short case study for one piece (brief, idea, process, result, learning)','Complete the creative project to a publishable standard','Improve the project based on peer testing','Explain basic freelance terms (brief, deliverables, revisions, deadline, rate) in simple language']::text[],array['Project check-in','What makes a strong portfolio','Creative project production','Stretch break','Peer testing','Revise and prepare the showcase','Showcase briefing and homework']::text[],'{}'::text[],'Completed creative project (video, photo set, branded designs); Content portfolio with three to five pieces, case-study notes and contact details; Completed credit and consent log; Showcase presentation draft','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 2 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='content' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,4,8,'Content showcase','Present your creative project and portfolio, explain your creative choices, give and receive feedback, pitch yourself and plan your next 30 days of content.',120,array['Present the creative project and portfolio clearly in three minutes','Explain at least one creative choice and one responsible-content choice','Give and receive feedback professionally using the rubric','Pitch themselves as a creator with the portfolio as proof','Write a 30-day content plan']::text[],array['Showcase set-up and expectations','Project presentations and questions - block 1','Stretch break','Project presentations and questions - block 2','Feedback round','Pitching yourself and workplace readiness','30-day content plan','Celebration and close']::text[],'{}'::text[],'Presented creative project and portfolio (final project) with rubric score and feedback; Portfolio message and creator pitch; 30-day content plan; Written feedback given to two peers','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 3 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='content' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,2,3,'Opportunity spotting','Identify customer needs and business opportunities; distinguish assumptions from evidence.',120,array['Identify business opportunities from problems, trends, skills and resources in their community','Describe a customer problem in terms of the job the customer is trying to do, their pains and the gains they want','Distinguish assumptions from evidence and list the riskiest assumptions in an idea','Plan simple market research using primary (observation, interviews, surveys) and secondary (reports, data) sources','Describe a target market and early adopters for an idea','Conduct a practice customer interview using good, non-leading questions','Write a one-page opportunity statement']::text[],array['Welcome to Entrepreneurship & Business and track overview','Identifying business opportunities','Understanding customer problems','Market research and target markets','Stretch break','Demonstration - good and bad customer interviews','Interview guide and practice interviews','Opportunity statement','Wrap-up and homework']::text[],'{}'::text[],'Three community problems and an opportunity chosen with the filter; Interview guide (eight to ten questions); One-page opportunity statement with top three assumptions','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='entrepreneurship' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,activities,topics,expected_output,assessment_notes,source,is_approved) select '00000000-0000-0000-0000-0000000000a1',t.id,2,4,'Value proposition and business model','Describe customer value and map a simple business model.',120,array['Simplified business model canvas','Peer challenge']::text[],array['Introduction to digital marketing','Social media marketing (Facebook, Instagram, TikTok, LinkedIn)','Content planning and creation','Canva for marketing graphics','Marketing copywriting, captions and calls to action','WhatsApp Business','Digital advertising fundamentals','SEO fundamentals','Marketing analytics and measuring campaign performance','Developing a practical digital marketing strategy']::text[],'One-page business model','Approved by DIRA (8 Nov 2026), including the digital marketing topics.','curriculum_docx + master_instruction_proposal',true from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='entrepreneurship' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,3,5,'Basic venture finance','Identify start-up and operating costs, price, revenue and simple cash flow.',120,array['Explain why business and personal money must be separated and how to keep simple records (including M-Pesa statements)','Describe the risks and costs of borrowing (digital loans, Hustler Fund, chamas, SACCOs, banks)','Classify start-up and operating costs, and fixed and variable costs','Calculate variable cost per unit, contribution per unit, gross profit and fully allocated unit cost, and set a price using cost-plus, competitor and value methods','Calculate break-even in units using contribution per unit','Explain the difference between profit and cash flow, and build a one-month cash-flow estimate','Outline a lean one-page business plan']::text[],array['Recap and cost hunt results','Basic financial literacy for entrepreneurs','Costing','Pricing and break-even','Stretch break','Revenue, expenses and cash flow','Start-up budget and one-month cash flow','Lean one-page business plan','Wrap-up and homework']::text[],'{}'::text[],'Start-up budget with researched prices; Variable and fully allocated unit cost, price, contribution per unit, gross profit and break-even calculation; One-month cash-flow estimate; Lean one-page business plan outline (started)','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 6 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='entrepreneurship' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,3,6,'Marketing and customer experience','Choose channels, create marketing messages and practise ethical selling.',120,array['Describe a simple brand for a small business (name, promise, look) and position it against alternatives','Build a one-page marketing plan (target customer, message, channels, offer, budget, measures)','Map the customer journey and design service standards for key moments','Handle a customer complaint professionally','Use ethical sales techniques - needs questions, benefits, handling objections, closing','Negotiate with a supplier or customer using preparation, options and a walk-away point']::text[],array['Recap and price reactions','Branding and marketing a small business','One-page marketing plan','Customer service and customer experience','Stretch break','Customer journey map and complaint role-play','Sales and negotiation','Sales and negotiation role-play and sales script','Wrap-up and homework']::text[],'{}'::text[],'One-page marketing plan; Customer journey map with service standards; Sales script','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 5 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='entrepreneurship' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,4,7,'Test and pitch','Use feedback to improve an idea and present a concise business pitch.',120,array['Design a test of their riskiest assumption (pre-orders, a pilot, a sample sale, a landing page or WhatsApp catalogue test)','Define what result would support or reject the assumption before testing','Interpret test evidence and decide to continue, change or stop','Complete a lean one-page business plan including legal basics and funding options as next steps','Build a 3-minute pitch (problem, solution, customer, evidence, model, money, team, ask)','Give and use peer feedback to improve the pitch']::text[],array['Recap and sales script results','Testing business ideas','Design your test','Completing the lean business plan','Stretch break','Pitch structure','Build your pitch','Peer pitch review']::text[],'{}'::text[],'Test card (and results if already tested); Completed lean one-page business plan; Three-minute pitch with up to five slides or a one-page visual; Peer review notes and revised assumptions','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 4 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='entrepreneurship' on conflict do nothing;
insert into curriculum_sessions(programme_id,track_id,week_no,session_no,title,description,duration_minutes,objectives,activities,topics,expected_output,assessment_notes,source) select '00000000-0000-0000-0000-0000000000a1',t.id,4,8,'Business pitch showcase','Present an early-stage business concept and identify a realistic validation step.',120,array['Deliver a 3-minute business pitch with evidence and a specific ask','Answer questions about customers, numbers and assumptions','Give and receive feedback professionally using the rubric','Pitch themselves as entrepreneurs and as employable young people using the project as proof','Write a 30-day validation action plan']::text[],array['Showcase set-up and expectations','Pitches and questions - block 1','Stretch break','Pitches and questions - block 2','Feedback round','Pitching yourself and workplace readiness','30-day validation action plan','Celebration and close']::text[],'{}'::text[],'Delivered business pitch (final project) with rubric score and feedback; Business concept summary (submitted in DIRA LEARN); 30-day validation action plan; Written feedback given to two peers','DRAFT (V13.2 curriculum revision, 19 Nov 2026): full lesson plan with timed segments, activities, assessment and facilitator notes. Assessment: 3 questions or tasks, checked against the expected outputs. Needs approval by programme management.','curriculum_v13' from tracks t where t.programme_id='00000000-0000-0000-0000-0000000000a1' and t.code='entrepreneurship' on conflict do nothing;
insert into system_settings(key,value,is_approved,note) values
('assessment_weights','{"engagement":20,"tasks_portfolio":30,"final_project":40,"reflection_action_plan":10}',false,'DRAFT recommendation from curriculum docx; requires management approval'),
('attendance_threshold','{"min_sessions":6,"of":8,"require_core":true}',false,'DRAFT; requires management approval'),
('track_selection_requires_core_complete','true',false,'Configurable enrolment rule; confirm with programme management'),
('competency_levels','["not_yet_assessed","developing","competent","advanced"]',false,'Configurable') on conflict do nothing;

-- Initial Curriculum Approval Centre queue (24 pending topics; approves nothing). Idempotent.
select seed_initial_topic_proposals();

-- V13 curriculum: lesson plans and teaching notes for every session (draft until approved). Idempotent; changes no duration.
do $$ begin if to_regprocedure('public.load_curriculum_v13()') is not null then perform load_curriculum_v13(); end if; end $$;
do $$ begin if to_regprocedure('public.apply_curriculum_v13_1()') is not null then perform apply_curriculum_v13_1(); end if; end $$;
do $$ begin if to_regprocedure('public.apply_curriculum_v13_2()') is not null then perform apply_curriculum_v13_2(); end if; end $$;

-- DIRA's 8 Nov 2026 approval of Digital Marketing Sessions 5-7 (migration 37): Digital Marketing topic proposals on their V13.2
-- sessions, approval noted on proposals and draft records. Approves nothing; idempotent.
do $$ begin if to_regprocedure('public.apply_digital_marketing_approval_37()') is not null then perform apply_digital_marketing_approval_37(); end if; end $$;
;
commit;
\echo '== done: run 02_verify_readonly.sql next'
\set QUIET off
select (select count(*) from supabase_migrations.schema_migrations) as migrations_recorded,
       has_table_privilege('authenticated', 'public.profiles', 'select') as profiles_readable_by_signed_in_users,
       (select count(*) from public.organizations) as organizations, (select count(*) from public.programmes) as programmes,
       (select count(*) from public.tracks) as tracks, (select count(*) from public.curriculum_sessions) as sessions,
       (select count(*) from auth.users) as sign_in_accounts,
       (select count(*) from auth.users u where not exists (select 1 from public.profiles p where p.id = u.id)) as accounts_without_profile;
